using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net;
using System.Text;
using System.Threading.Tasks;
using ReFix.Shared;
namespace ReFix.Hub {
 public sealed partial class ModuleManager {
  internal Func<string,long,bool,byte[]> SourceFetch=DownloadSource;
  SourceSnapshot sources=new SourceSnapshot(new string[0],new RepositorySource[0]);
  readonly List<string> sourceErrors=new List<string>();volatile string[] publishedSourceErrors=new string[0];
  public string DataRoot {get{return root;}}
  public IList<string> SourceErrors {get{return Array.AsReadOnly(publishedSourceErrors);}}
  internal static bool ReservedSourceId(string id){return id=="quiet-mixer"||id=="quick-note"||id=="task-menu";}
  bool Configured(ModuleManifest m){if(string.IsNullOrEmpty(m.SourceRepository)&&string.IsNullOrEmpty(m.SourceFolder))return true;var current=new SharedSourceStore(root).Read();return !string.IsNullOrEmpty(m.SourceRepository)&&string.IsNullOrEmpty(m.SourceFolder)&&current.Repositories.Any(r=>r.Repository==m.SourceRepository)||string.IsNullOrEmpty(m.SourceRepository)&&!string.IsNullOrEmpty(m.SourceFolder)&&current.Folders.Contains(m.SourceFolder,StringComparer.OrdinalIgnoreCase);}
  internal void EnsureInstallSource(ModuleManifest m){m.Validate();if(!Configured(m))throw new InvalidDataException("This module source is no longer configured.");}
  void LoadSources(bool network){
   sourceErrors.Clear();try{sources=new SharedSourceStore(root).Read();}catch(Exception e){sources=new SourceSnapshot(new string[0],new RepositorySource[0]);sourceErrors.Add("Sources: "+e.Message);}
   var combined=MergeCatalog(null);var ids=new HashSet<string>(combined.Modules.Select(m=>m.Id),StringComparer.Ordinal);
   // Rebuild advertised external versions from current sources; installed records reserve their IDs and origin.
   combined.Modules.RemoveAll(m=>!string.IsNullOrEmpty(m.SourceRepository)||!string.IsNullOrEmpty(m.SourceFolder));
   IncludeInstalledSources(combined);
   ids=new HashSet<string>(combined.Modules.Select(m=>m.Id),StringComparer.Ordinal);
   Action<CatalogDocument,string> add=(doc,label)=>{foreach(var m in doc.Modules){if(ReservedSourceId(m.Id)){sourceErrors.Add(label+": reserved module ID "+m.Id);continue;}var old=combined.Modules.FirstOrDefault(x=>x.Id==m.Id);if(old!=null){if(old.SourceRepository!=m.SourceRepository||old.SourceFolder!=m.SourceFolder){sourceErrors.Add(label+": module ID collision "+m.Id);continue;}if(new Version(old.Version)>new Version(m.Version))continue;combined.Modules.Remove(old);}combined.Modules.Add(m);ids.Add(m.Id);}};
   foreach(string folder in sources.Folders)try{add(ReadFolder(folder),folder);}catch(Exception e){sourceErrors.Add(folder+": "+e.Message);}
   foreach(var source in sources.Repositories){string file=SourceCache(source.Repository);CatalogDocument doc=null;if(network){foreach(string url in SourcePolicy.Catalogs(source))try{string raw=Encoding.UTF8.GetString(SourceFetch(url,1024*1024,false));doc=ReadSourceCatalog(raw,source.Repository,null);Atomic(file,raw);break;}catch(Exception e){sourceErrors.Add(url+": "+e.Message);}}if(doc==null&&File.Exists(file))try{if(new FileInfo(file).Length>1024*1024)throw new InvalidDataException("Cached source too large.");doc=ReadSourceCatalog(File.ReadAllText(file),source.Repository,null);}catch(Exception e){sourceErrors.Add(source.Repository+" cache: "+e.Message);}if(doc!=null)add(doc,source.Repository);}
   IncludeInstalledSources(combined);
   publishedSourceErrors=sourceErrors.ToArray();Apply(combined);
  }
  void IncludeInstalledSources(CatalogDocument combined){foreach(string directory in Directory.EnumerateDirectories(Path.Combine(root,"modules")))try{if((File.GetAttributes(directory)&FileAttributes.ReparsePoint)!=0)continue;string current=Path.Combine(directory,"current.json");if(!File.Exists(current)||new FileInfo(current).Length>1024)continue;string version=Json().Deserialize<string>(File.ReadAllText(current));if(!System.Text.RegularExpressions.Regex.IsMatch(version??"","^[0-9]{1,5}\\.[0-9]{1,5}\\.[0-9]{1,5}(\\.[0-9]{1,5})?$"))continue;string installedDirectory=Path.Combine(directory,version);if((File.GetAttributes(installedDirectory)&FileAttributes.ReparsePoint)!=0)continue;string metadata=Path.Combine(installedDirectory,"installed.json");if(!File.Exists(metadata)||new FileInfo(metadata).Length>1024*1024||(File.GetAttributes(metadata)&FileAttributes.ReparsePoint)!=0)continue;var record=Json().Deserialize<InstalledRecord>(File.ReadAllText(metadata));if(record==null||record.Manifest==null)continue;var m=record.Manifest;m.Validate();if(m.Id!=Path.GetFileName(directory)||m.Version!=version||ReservedSourceId(m.Id)||(string.IsNullOrEmpty(m.SourceRepository)&&string.IsNullOrEmpty(m.SourceFolder))||combined.Modules.Any(x=>x.Id==m.Id))continue;string verifiedDirectory;Installed(new ModuleView{Manifest=m},out verifiedDirectory);combined.Modules.Add(m);}catch(Exception e){sourceErrors.Add("Installed source "+Path.GetFileName(directory)+": "+e.Message);}}
  string SourceCache(string repository){using(var h=System.Security.Cryptography.SHA256.Create()){string id=BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(repository))).Replace("-","");string dir=Path.Combine(root,"source-catalogs");Directory.CreateDirectory(dir);return Path.Combine(dir,id+".json");}}
  internal static CatalogDocument ReadSourceCatalog(string text,string repository,string folder){if(text==null||text.Length>1024*1024)throw new InvalidDataException("Catalogue too large.");var d=Json().Deserialize<CatalogDocument>(text.TrimStart('\uFEFF'));if(d==null||d.SchemaVersion!=1||d.Modules==null||d.Modules.Count>200)throw new InvalidDataException("Invalid catalogue schema.");var ids=new HashSet<string>();foreach(var m in d.Modules){if(m==null)throw new InvalidDataException("Null module.");m.SourceRepository=repository??"";m.SourceFolder=folder??"";m.SourcePackageFile="";m.Validate();if(string.IsNullOrEmpty(m.Sha256))throw new InvalidDataException("Source module requires SHA256.");if(!ids.Add(m.Id))throw new InvalidDataException("Duplicate module ID.");}return d;}
  CatalogDocument ReadFolder(string folder){if(!Directory.Exists(folder))throw new DirectoryNotFoundException("Extension folder unavailable.");if((File.GetAttributes(folder)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Linked source folders are forbidden.");string catalog=Path.Combine(folder,"catalog.json");if(!File.Exists(catalog))catalog=Path.Combine(folder,"catalog","catalog.json");if(File.Exists(catalog)){if(new FileInfo(catalog).Length>1024*1024)throw new InvalidDataException("Catalogue too large.");return ReadSourceCatalog(File.ReadAllText(catalog),null,folder);}
   var result=new CatalogDocument{SchemaVersion=1,Modules=new List<ModuleManifest>()};foreach(string zipPath in Directory.EnumerateFiles(folder,"*.zip").Take(201)){if(result.Modules.Count>=200)throw new InvalidDataException("Too many packages in one folder.");try{if(new FileInfo(zipPath).Length>PackageSafety.MaxArchive||(File.GetAttributes(zipPath)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Invalid local archive.");using(var zip=ZipFile.OpenRead(zipPath)){var entries=zip.Entries.Where(e=>e.FullName=="module.json").ToArray();if(entries.Length!=1||entries[0].Length>65536)throw new InvalidDataException("A single root module.json is required.");ModuleManifest m;using(var reader=new StreamReader(entries[0].Open())){char[] buffer=new char[65537];int total=0,n;while(total<buffer.Length&&(n=reader.Read(buffer,total,buffer.Length-total))>0)total+=n;if(total>65536)throw new InvalidDataException("Module metadata too large.");m=Json().Deserialize<ModuleManifest>(new string(buffer,0,total));}m.SourceRepository="";m.SourceFolder=folder;m.SourcePackageFile=Path.GetFileName(zipPath);m.PackageUrl="";m.Sha256=PackageSafety.Hash(zipPath);m.Validate();if(result.Modules.Any(x=>x.Id==m.Id))throw new InvalidDataException("Duplicate local module ID.");result.Modules.Add(m);}}catch(Exception e){sourceErrors.Add(zipPath+": "+e.Message);}}return result;
  }
  public Task ReloadSourcesAsync(){return Work(()=>{LoadSources(true);foreach(var v in Modules)RefreshState(v);});}
  byte[] DownloadModulePackage(ModuleManifest manifest){EnsureInstallSource(manifest);if(string.IsNullOrEmpty(manifest.SourceRepository)){if(!string.IsNullOrEmpty(manifest.SourceFolder))throw new InvalidDataException("Local source packages must be installed from their configured folder.");ModuleManifest.ValidateUrl(manifest.PackageUrl);return Download(manifest.PackageUrl,PackageSafety.MaxArchive,true);}SourcePolicy.Package(manifest.PackageUrl,manifest.SourceRepository);return SourceFetch(manifest.PackageUrl,PackageSafety.MaxArchive,true);}
  static byte[] DownloadSource(string url,long max,bool package){SourcePolicy.Https(url);ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;string initial=url;var timer=Stopwatch.StartNew();for(int redirect=0;redirect<4;redirect++){var request=(HttpWebRequest)WebRequest.Create(url);request.AllowAutoRedirect=false;request.Timeout=15000;request.ReadWriteTimeout=15000;request.UserAgent="ReFIXHub/1.3";using(var response=(HttpWebResponse)request.GetResponse()){if((int)response.StatusCode>=300&&(int)response.StatusCode<400){string next=new Uri(new Uri(url),response.Headers["Location"]).AbsoluteUri;SourcePolicy.Redirect(initial,next,package);url=next;continue;}if(response.ContentLength>max)throw new InvalidDataException("Download too large.");using(var output=new MemoryStream())using(var input=response.GetResponseStream()){byte[] buffer=new byte[32768];int n;while((n=input.Read(buffer,0,buffer.Length))>0){if(timer.ElapsedMilliseconds>30000)throw new TimeoutException("Source download timed out.");if(output.Length+n>max)throw new InvalidDataException("Download too large.");output.Write(buffer,0,n);}return output.ToArray();}}}throw new IOException("Too many source redirects.");}
  string FindSourceBundle(ModuleManifest m){if(string.IsNullOrEmpty(m.SourceFolder))return null;EnsureInstallSource(m);foreach(string relative in string.IsNullOrEmpty(m.SourcePackageFile)?new[]{"packages/"+m.Id+"-"+m.Version+".zip",m.Id+"-"+m.Version+".zip"}:new[]{m.SourcePackageFile}){string file=PackageSafety.Inside(m.SourceFolder,relative);if(!File.Exists(file))continue;for(string p=file;p!=null&&p.Length>=m.SourceFolder.Length;p=Path.GetDirectoryName(p))if((File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Linked source paths are forbidden.");if(new FileInfo(file).Length>PackageSafety.MaxArchive||string.IsNullOrEmpty(m.Sha256)||!string.Equals(PackageSafety.Hash(file),m.Sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Local source package SHA256 mismatch.");return file;}return null;}
 }
}
